static uint32_t NextUtf8(std::string_view text,size_t& i){unsigned char a=static_cast<unsigned char>(text[i++]);if(a<0x80)return a;if((a&0xe0)==0xc0&&i<text.size())return((a&0x1f)<<6)|(static_cast<unsigned char>(text[i++])&0x3f);if((a&0xf0)==0xe0&&i+1<text.size()){uint32_t v=(a&0x0f)<<12;v|=(static_cast<unsigned char>(text[i++])&0x3f)<<6;v|=static_cast<unsigned char>(text[i++])&0x3f;return v;}if((a&0xf8)==0xf0&&i+2<text.size()){uint32_t v=(a&7)<<18;v|=(static_cast<unsigned char>(text[i++])&0x3f)<<12;v|=(static_cast<unsigned char>(text[i++])&0x3f)<<6;v|=static_cast<unsigned char>(text[i++])&0x3f;return v;}return'?';}
void DrawList::Text(Vec2 p,std::string_view text,float s,Color col){for(size_t i=0;i<text.size();){uint32_t code=NextUtf8(text,i);++stats_.textGlyphs;if(code<128){char ch=char(code);ch=ch>='a'&&ch<='z'?char(ch-32):ch;auto it=Font.find(ch);if(it!=Font.end())for(int y=0;y<7;++y){const unsigned char row=it->second[y];int x=0;while(x<5){if(!(row&(1<<(4-x)))){++x;continue;}const int start=x;while(++x<5&&row&(1<<(4-x))){}const int length=x-start;stats_.textSourcePixels+=length;++stats_.textSpans;stats_.totalTextSourcePixels+=length;++stats_.totalTextSpans;const float width=(float(length-1)+.82f)*s;Quad({p.x+(float(start)+float(length-1)*.5f)*s,p.y+y*s},{width,s*.82f},col);}}p.x+=6*s;continue;}const SystemGlyph& glyph=LoadSystemGlyph(code);const float pixel=7.f*s/18.f;stats_.textSourcePixels+=glyph.sourcePixels;stats_.textSpans+=glyph.spans.size();stats_.totalTextSourcePixels+=glyph.sourcePixels;stats_.totalTextSpans+=glyph.spans.size();for(const GlyphSpan&span:glyph.spans){const float width=float(span.length)*pixel;Quad({p.x+(float(span.x)+float(span.length)*.5f)*pixel,p.y+(float(span.y)+.5f)*pixel},{width,pixel},{col.r,col.g,col.b,col.a*(std::min)(1.f,float(span.coverage)/64.f)});}p.x+=(glyph.advance+1)*pixel;}}
